/** Every rule about "what does select mean right now" lives in one class. */
final class HasMoneyState implements State {

    @Override public void insert(VendingMachine m, Coin coin) {
        m.addCredit(coin);          // still collecting, stay put
    }

    @Override public void cancel(VendingMachine m) {
        m.refundCredit();           // legal here, and only here
        m.setState(new IdleState());
    }

    @Override public void select(VendingMachine m, String code) {
        if (!m.inventory().available(code))       { m.display("Sold out");       return; }
        int price = m.inventory().priceOf(code);
        if (m.credit() < price)                   { m.display("Insert more");    return; }

        // Check change BEFORE releasing the product. Releasing first and then
        // discovering you cannot make change is the bug that eats money.
        int changeDue = m.credit() - price;
        if (!m.coins().canMakeChange(changeDue))  { m.display("Exact change only"); return; }

        m.setState(new DispensingState());
        m.dispense(code, changeDue);
    }
}

/** Greedy is correct for canonical coin systems (1, 5, 10, 25 · 1, 2, 5, 10).
 *  Say that qualifier out loud — for an arbitrary set it is wrong, and the
 *  correct answer is the coin-change DP. */
List<Coin> dispenseChange(int amount) {
    List<Coin> out = new ArrayList<>();
    for (Coin coin : Coin.descending()) {
        while (amount >= coin.value() && held.get(coin) > 0) {
            amount -= coin.value();
            held.merge(coin, -1, Integer::sum);
            out.add(coin);
        }
    }
    if (amount != 0) throw new IllegalStateException("canMakeChange lied");
    return out;
}
